.eq_records<-function(value,name,key) {if(!is.list(value)||!is.null(names(value))) .cr_error('QUALITATIVE_CONTRACT',paste(name,'must be a record list'));rows<-lapply(value,function(r).ex_object(r,name));.ex_ids(lapply(rows,function(r)r[[key]]),key,TRUE);rows}
.eq_conditions<-function(conditions,criteria) {cc<-.ex_object(conditions,'conditions');if(!length(cc)||length(setdiff(names(cc),names(criteria)))) .cr_error('QUALITATIVE_CONDITION','Nonempty conditions must reference existing criteria');for(cid in names(cc)){ids<-.ex_ids(cc[[cid]],'condition levels');if(length(setdiff(ids,vapply(criteria[[cid]]$levels,function(v)v$level_id,character(1))))) .cr_error('QUALITATIVE_CONDITION','Unknown condition level')};cc}
compile_qualitative_rubric<-function(criteria,rubric_contract,score_policy,interactions=NULL,rating_limits=NULL,context=NULL) {
 rows<-.eq_records(criteria,'criteria','criterion_id');if(!length(rows)) .cr_error('QUALITATIVE_CONTRACT','At least one criterion required');contract<-.ex_object(rubric_contract,'rubric_contract');.ex_target(contract$target,context)
 for(k in c('rubric_id','version','population_id','reference')).cr_string(contract[[k]],k,'QUALITATIVE_CONTRACT');.cr_data_date(contract$known_at,'known_at');grades<-.ex_ids(contract$ordered_grades,'ordered_grades',TRUE);if(!identical(contract$score_direction,'higher_is_worse')) .cr_error('QUALITATIVE_DIRECTION','Points must explicitly increase with risk')
 policy<-.ex_object(score_policy,'score_policy');floor<-.ex_number(policy$score_floor,'score_floor');cap<-.ex_number(policy$score_cap,'score_cap');coverage<-.ex_probability(policy$minimum_evidence_coverage,'minimum_evidence_coverage');if(floor>=cap||!(policy$unresolved_interaction_policy%in%c('refer','apply_adverse'))) .cr_error('QUALITATIVE_POLICY','Ordered score bounds and unresolved interaction policy required')
 for(i in seq_along(rows)){criterion<-rows[[i]];weight<-.ex_number(criterion$weight,'weight');if(weight<0) .cr_error('QUALITATIVE_WEIGHT','Weights cannot be negative');.ex_ids(criterion$required_evidence_types,'required_evidence_types');minimum<-.ex_integer(criterion$minimum_independent_sources,'minimum_independent_sources',10000);if(!minimum) .cr_error('QUALITATIVE_EVIDENCE','Positive independent evidence group count required')
 if(!(criterion$missing_policy%in%c('refer','worst'))||!(criterion$not_applicable_policy%in%c('refer','worst','fixed'))) .cr_error('QUALITATIVE_MISSING','Explicit missing and non-applicable policies required');levels<-.eq_records(criterion$levels,'levels','level_id');if(!length(levels)) .cr_error('QUALITATIVE_LEVEL','At least one criterion level required');points<-vapply(levels,function(v).ex_number(v$points,'points'),numeric(1));kind<-criterion$kind
 if(identical(kind,'categorical')){categories<-.ex_ids(criterion$categories,'categories');assigned<-unlist(lapply(levels,function(v).ex_ids(v$values,'level values')),use.names=FALSE);if(anyDuplicated(assigned)||!setequal(assigned,categories)) .cr_error('QUALITATIVE_COVERAGE','Levels must partition declared categories exactly')
 }else if(identical(kind,'numeric')){for(level in levels){low<-.ex_number(level$lower,'lower');high<-.ex_number(level$upper,'upper');if(low>=high) .cr_error('QUALITATIVE_LEVEL','Numeric intervals must be nonempty')};levels<-levels[order(vapply(levels,function(v)v$lower,numeric(1)))];if(length(levels)>1L)for(j in seq_len(length(levels)-1L))if(levels[[j]]$upper!=levels[[j+1L]]$lower) .cr_error('QUALITATIVE_COVERAGE','Numeric levels must be contiguous without overlap');direction<-criterion$risk_order;if(!(direction%in%c('increasing','decreasing','none'))) .cr_error('QUALITATIVE_DIRECTION','Declare numeric risk_order');changes<-diff(vapply(levels,function(v)v$points,numeric(1)));if((direction=='increasing'&&any(changes<0))||(direction=='decreasing'&&any(changes>0))) .cr_error('QUALITATIVE_DIRECTION','Points violate risk direction')
 }else .cr_error('QUALITATIVE_LEVEL','kind must be categorical or numeric')
 if(criterion$not_applicable_policy=='fixed'){fixed<-.ex_number(criterion$not_applicable_points,'not_applicable_points');if(fixed<min(points)||fixed>max(points)) .cr_error('QUALITATIVE_MISSING','Non-applicable fixed points outside criterion range')};criterion$levels<-levels;rows[[i]]<-criterion
 }
 maximum<-max(vapply(rows,function(r)r$weight,numeric(1)));if(maximum<=0) .cr_error('QUALITATIVE_WEIGHT','Positive total weight required');denominator<-sum(vapply(rows,function(r)r$weight/maximum,numeric(1)));for(i in seq_along(rows))rows[[i]]$normalized_weight<-(rows[[i]]$weight/maximum)/denominator
 mapping<-setNames(rows,vapply(rows,function(r)r$criterion_id,character(1)));rules<-.eq_records(if(is.null(interactions))list()else interactions,'interactions','interaction_id');limits<-.eq_records(if(is.null(rating_limits))list()else rating_limits,'rating_limits','limit_id')
 for(i in seq_along(rules)){rule<-rules[[i]];rule$conditions<-.eq_conditions(rule$conditions,mapping);delta<-.ex_number(rule$points_delta,'points_delta');if(delta<0) .cr_error('QUALITATIVE_INTERACTION','Only adverse nonnegative interactions supported');.cr_string(rule$reference,'reference','QUALITATIVE_CONTRACT');rules[[i]]<-rule}
 for(i in seq_along(limits)){rule<-limits[[i]];rule$conditions<-.eq_conditions(rule$conditions,mapping);if(!(rule$best_allowed_grade%in%grades)||!(rule$worst_allowed_grade%in%grades)||match(rule$best_allowed_grade,grades)>match(rule$worst_allowed_grade,grades)) .cr_error('QUALITATIVE_LIMIT','Rating limit must be nonempty on declared grades');.cr_string(rule$reference,'reference','QUALITATIVE_CONTRACT');limits[[i]]<-rule}
 potential<-sum(vapply(rows,function(r)max(vapply(r$levels,function(l)l$points,numeric(1)))*r$normalized_weight,numeric(1)))+sum(vapply(rules,function(r)r$points_delta,numeric(1)));if(!is.finite(potential)) .cr_error('QUALITATIVE_SCALE','Potential score outside finite range')
 value<-.ex_seal(list(rubric_contract=contract,score_policy=policy,criteria=rows[order(vapply(rows,function(r)r$criterion_id,character(1)))],interactions=rules[order(vapply(rules,function(r)r$interaction_id,character(1)))],rating_limits=limits[order(vapply(limits,function(r)r$limit_id,character(1)))]),'rubric_hash')
 .cr_result(value,'expert.compile_qualitative_rubric','qualitative_rubric',context,limitations='Higher points mean greater risk. Fixed normalized weights do not change with missingness. Unknown criteria refer or take worst points; evidenced non-applicability has its own policy. Numeric levels are left closed/right open, including the final upper endpoint.')
}
.eq_available<-function(record,asof,knowledge,observation=FALSE) {begin<-.cr_data_date(record$valid_from,'valid_from');end<-if(is.null(record$valid_until))NULL else .cr_data_date(record$valid_until,'valid_until');known<-.cr_data_date(record$known_at,'known_at');if(!is.null(end)&&end<=begin) .cr_error('QUALITATIVE_DATE','Empty validity interval');observed<-if(observation).cr_data_date(record$observed_at,'observed_at')else NULL;if(observation&&known<observed) .cr_error('QUALITATIVE_DATE','Observation cannot be known before it occurs');if(known>knowledge)return('NOT_KNOWN');if(asof<begin||(!is.null(end)&&asof>=end)||(observation&&observed>asof))return('NOT_VALID');NULL}

evaluate_qualitative_evidence<-function(compiled_rubric,observations,evidence,as_of,known_at,conflicts=NULL,context=NULL) {
 rubric<-.ex_read(compiled_rubric,'rubric_hash');contract<-rubric$rubric_contract;.ex_target(contract$target,context);asof<-.cr_data_date(as_of,'as_of');knowledge<-.cr_data_date(known_at,'known_at');if(.cr_data_date(contract$known_at,'rubric known_at')>knowledge) .cr_error('QUALITATIVE_LOOKAHEAD','Rubric unavailable at knowledge cutoff')
 criteria<-setNames(rubric$criteria,vapply(rubric$criteria,function(r)r$criterion_id,character(1)));obs<-.eq_records(observations,'observations','observation_id');ev<-.eq_records(evidence,'evidence','evidence_id');cf<-.eq_records(if(is.null(conflicts))list()else conflicts,'conflicts','conflict_id');evidence_map<-list();exclusions<-list()
 for(row in ev){for(k in c('evidence_type','source_id','independence_group','content_fingerprint')).cr_string(row[[k]],k,'QUALITATIVE_EVIDENCE');if(!(row$status%in%c('VERIFIED','UNVERIFIED','REJECTED'))) .cr_error('QUALITATIVE_EVIDENCE','Verification status required');reason<-.eq_available(row,asof,knowledge);if(is.null(reason)&&row$status!='VERIFIED')reason<-row$status;evidence_map[[row$evidence_id]]<-list(row=row,reason=reason);if(!is.null(reason))exclusions[[length(exclusions)+1L]]<-list(record_type='evidence',record_id=row$evidence_id,reason=reason)}
 active<-setNames(rep(list(list()),length(criteria)),names(criteria));obs_map<-setNames(obs,vapply(obs,function(r)r$observation_id,character(1)))
 for(row in obs){if(!(row$criterion_id%in%names(criteria))||!is.logical(row$not_applicable)||length(row$not_applicable)!=1L||is.na(row$not_applicable)) .cr_error('QUALITATIVE_OBSERVATION','Known criterion and explicit non-applicable flag required');if(!('value'%in%names(row))||(row$not_applicable&&!is.null(row$value))) .cr_error('QUALITATIVE_OBSERVATION','Value required; non-applicable must have null value');eids<-.ex_ids(row$evidence_ids,'evidence_ids',TRUE);if(length(setdiff(eids,names(evidence_map)))) .cr_error('QUALITATIVE_EVIDENCE','Unknown referenced evidence');reason<-.eq_available(row,asof,knowledge,TRUE);if(!is.null(reason))exclusions[[length(exclusions)+1L]]<-list(record_type='observation',record_id=row$observation_id,reason=reason)else active[[row$criterion_id]][[length(active[[row$criterion_id]])+1L]]<-row}
 active_conflicts<-setNames(rep(list(list()),length(criteria)),names(criteria))
 for(row in cf){ids<-.ex_ids(row$observation_ids,'conflict observation_ids');if(length(ids)<2L||length(setdiff(ids,names(obs_map)))||length(unique(vapply(ids,function(i)obs_map[[i]]$criterion_id,character(1))))!=1L) .cr_error('QUALITATIVE_CONFLICT','Conflict must link known observations of one criterion');if(!(row$status%in%c('OPEN','RESOLVED'))) .cr_error('QUALITATIVE_CONFLICT','Conflict status required');.cr_string(row$reference,'reference','QUALITATIVE_CONFLICT');if(row$status=='RESOLVED'&&!(row$resolution_observation_id%in%ids)) .cr_error('QUALITATIVE_CONFLICT','Resolution must select a linked observation');reason<-.eq_available(row,asof,knowledge);if(!is.null(reason))exclusions[[length(exclusions)+1L]]<-list(record_type='conflict',record_id=row$conflict_id,reason=reason)else{cid<-obs_map[[ids[1]]]$criterion_id;active_conflicts[[cid]][[length(active_conflicts[[cid]])+1L]]<-row}}
 results<-list();unresolved<-FALSE;assumptions<-FALSE
 for(cid in names(criteria)){criterion<-criteria[[cid]];records<-active[[cid]];reasons<-character();applicable_conflicts<-active_conflicts[[cid]];selected<-unique(unlist(lapply(Filter(function(r)r$status=='RESOLVED',applicable_conflicts),function(r)r$resolution_observation_id),use.names=FALSE));if(any(vapply(applicable_conflicts,function(r)r$status=='OPEN',logical(1)))||length(selected)>1L)reasons<-c(reasons,'EXPLICIT_CONFLICT')
 if(length(selected)){chosen<-selected[1];removed<-unique(unlist(lapply(Filter(function(r)r$status=='RESOLVED',applicable_conflicts),function(r)setdiff(unlist(r$observation_ids),chosen)),use.names=FALSE));records<-Filter(function(r)!(r$observation_id%in%removed),records);if(!(chosen%in%vapply(records,function(r)r$observation_id,character(1))))reasons<-c(reasons,'RESOLUTION_UNAVAILABLE')}
 facts<-unique(vapply(records,function(r).cr_hash(list(value=r$value,not_applicable=r$not_applicable)),character(1)));if(length(facts)>1L)reasons<-c(reasons,'CONFLICTING_OBSERVATIONS');eids<-sort(unique(unlist(lapply(records,function(r)r$evidence_ids),use.names=FALSE)));usable<-lapply(Filter(function(r)is.null(r$reason),evidence_map[eids]),function(r)r$row);types<-vapply(usable,function(r)r$evidence_type,character(1));groups<-unique(unname(vapply(usable,function(r)r$independence_group,character(1))));covered<-length(records)>0L&&all(unlist(criterion$required_evidence_types)%in%types)&&length(groups)>=criterion$minimum_independent_sources&&!length(reasons);points<-level<-NULL;status<-'UNRESOLVED';minimum<-min(vapply(criterion$levels,function(r)r$points,numeric(1)));maximum<-max(vapply(criterion$levels,function(r)r$points,numeric(1)))
 if(length(reasons)){status<-'CONFLICT';unresolved<-TRUE}else if(!covered){reasons<-c(reasons,if(!length(records))'NO_OBSERVATION'else 'EVIDENCE_GAP');if(criterion$missing_policy=='worst'){points<-maximum;status<-'ASSUMED_WORST';assumptions<-TRUE}else unresolved<-TRUE
 }else if(records[[1]]$not_applicable){if(criterion$not_applicable_policy=='refer'){reasons<-c(reasons,'NON_APPLICABLE_REFER');unresolved<-TRUE}else{points<-if(criterion$not_applicable_policy=='worst')maximum else criterion$not_applicable_points;status<-'EVIDENCED_NOT_APPLICABLE'}
 }else{value<-records[[1]]$value;matched<-list();if(criterion$kind=='categorical'){matched<-Filter(function(r)is.character(value)&&length(value)==1L&&value%in%unlist(r$values),criterion$levels)}else{value<-tryCatch(.ex_number(value,'observation value'),error=function(e)NULL);if(!is.null(value))for(j in seq_along(criterion$levels)){rr<-criterion$levels[[j]];if(rr$lower<=value&&(value<rr$upper||(j==length(criterion$levels)&&value==rr$upper)))matched[[length(matched)+1L]]<-rr}}
 if(!length(matched)){reasons<-c(reasons,'OUT_OF_DOMAIN');unresolved<-TRUE;covered<-FALSE}else{level<-matched[[1]]$level_id;points<-matched[[1]]$points;status<-'OBSERVED'}}
 results[[length(results)+1L]]<-list(criterion_id=cid,status=status,level_id=level,points=points,normalized_weight=criterion$normalized_weight,weighted_contribution=if(is.null(points))NULL else points*criterion$normalized_weight,contribution_interval=as.list(c(if(is.null(points))minimum else points,if(is.null(points))maximum else points)*criterion$normalized_weight),evidence_covered=covered,observation_ids=as.list(sort(vapply(records,function(r)r$observation_id,character(1)))),evidence_ids=as.list(eids),eligible_evidence_ids=as.list(unname(sort(vapply(usable,function(r)r$evidence_id,character(1))))),independent_groups=as.list(sort(groups)),conflict_ids=as.list(sort(vapply(applicable_conflicts,function(r)r$conflict_id,character(1)))),reasons=as.list(reasons))
 }
 lookup<-setNames(results,vapply(results,function(r)r$criterion_id,character(1)))
 condition<-function(conditions){unknown<-FALSE;for(cid in names(conditions)){level<-lookup[[cid]]$level_id;if(is.null(level))unknown<-TRUE else if(!(level%in%unlist(conditions[[cid]])))return(FALSE)};if(unknown)NULL else TRUE}
 interactions<-list();low_delta<-high_delta<-delta<-0
 for(rule in rubric$interactions){matched<-condition(rule$conditions);applied<-identical(matched,TRUE)||(is.null(matched)&&rubric$score_policy$unresolved_interaction_policy=='apply_adverse');if(is.null(matched)){if(!applied)unresolved<-TRUE else assumptions<-TRUE};low_delta<-low_delta+if(applied)rule$points_delta else 0;high_delta<-high_delta+if(!identical(matched,FALSE))rule$points_delta else 0;delta<-delta+if(applied)rule$points_delta else 0;interactions[[length(interactions)+1L]]<-list(interaction_id=rule$interaction_id,condition_matched=matched,applied=applied,points_delta=if(applied)rule$points_delta else 0,unresolved=is.null(matched))}
 grades<-unlist(contract$ordered_grades);lo<-1L;hi<-length(grades);limits<-list()
 for(rule in rubric$rating_limits){matched<-condition(rule$conditions);if(is.null(matched))unresolved<-TRUE else if(matched){lo<-max(lo,match(rule$best_allowed_grade,grades));hi<-min(hi,match(rule$worst_allowed_grade,grades))};limits[[length(limits)+1L]]<-list(limit_id=rule$limit_id,condition_matched=matched,best_allowed_grade=rule$best_allowed_grade,worst_allowed_grade=rule$worst_allowed_grade)}
 rating_conflict<-length(grades)>0L&&lo>hi;if(rating_conflict)unresolved<-TRUE;coverage<-sum(vapply(Filter(function(r)r$evidence_covered,results),function(r)r$normalized_weight,numeric(1)));coverage_failed<-coverage<rubric$score_policy$minimum_evidence_coverage;if(coverage_failed)unresolved<-TRUE
 clip<-function(p)max(rubric$score_policy$score_floor,min(rubric$score_policy$score_cap,p));bounds<-c(clip(sum(vapply(results,function(r)r$contribution_interval[[1]],numeric(1)))+low_delta),clip(sum(vapply(results,function(r)r$contribution_interval[[2]],numeric(1)))+high_delta));score<-if(any(vapply(results,function(r)is.null(r$points),logical(1)))||any(vapply(interactions,function(r)r$unresolved&&!r$applied,logical(1))))NULL else clip(sum(vapply(results,function(r)r$weighted_contribution,numeric(1)))+delta)
 exclusions<-exclusions[order(vapply(exclusions,function(r)r$record_type,character(1)),vapply(exclusions,function(r)r$record_id,character(1)))]
 .cr_result(list(score=score,score_interval=as.list(bounds),status=if(unresolved)'REFER'else if(assumptions)'READY_WITH_ASSUMPTIONS'else 'READY',evidence_coverage=coverage,minimum_coverage_failed=coverage_failed,criterion_results=results,interaction_results=interactions,rating_limits=limits,rating_limit_conflict=rating_conflict,permitted_grade_interval=if(!length(grades)||rating_conflict)NULL else as.list(grades[c(lo,hi)]),excluded_records=exclusions,observations_hash=.cr_hash(obs[order(vapply(obs,function(r)r$observation_id,character(1)))]),evidence_hash=.cr_hash(ev[order(vapply(ev,function(r)r$evidence_id,character(1)))]),conflicts_hash=.cr_hash(cf[order(vapply(cf,function(r)r$conflict_id,character(1)))]),rubric_hash=rubric$rubric_hash,as_of=as_of,known_at=known_at,target=contract$target),'expert.evaluate_qualitative_evidence','qualitative_points',context,limitations='Only supplied structured facts and verified dated evidence are used. Independence groups are caller declarations. Conflicting facts refer until explicit dated resolution. A numeric score with REFER status is not approval. Points are not automatically PD.')
}
